    10	    @Override
    11	    public MatchResult search(CharSequence pattern, CharSequence text) {
    12	        int m = pattern.length();
    13	        int n = text.length();
    14	        int patHash = hashCalculator.hash(pattern, m);
    15	        int h = hashCalculator.highOrderFactor(m);
    16	        TextWindow window = new TextWindow(text, 0, m);
    17	        int txtHash = hashCalculator.hash(window, window.length());
    18	        MatchResult result = new MatchResult(n - m + 1);
    19	        while (window.start() <= n - m) {
    20	            if (patHash == txtHash && window.startsWith(pattern)) {
    21	                result.add(window.start());
    22	            }
    23	            if (window.start() < n - m) {
    24	                txtHash = hashCalculator.roll(txtHash, window.leaving(), window.entering(), h);
    25	            }
    26	            window = window.slide();
    27	        }
    28	        return result;
    29	    }
