     1	package rabinkarp;
     2	
     3	import stringsearch.HashCalculator;
     4	
     5	public final class PolynomialHashCalculator implements HashCalculator {
     6	    private final int radix;
     7	    private final int modulus;
     8	
     9	    public PolynomialHashCalculator(int radix, int modulus) {
    10	        this.radix = radix;
    11	        this.modulus = modulus;
    12	    }
    13	
    14	    @Override
    15	    public int hash(CharSequence seq, int length) {
    16	        int hash = 0;
    17	        for (int i = 0; i < length; i++) {
    18	            hash = (radix * hash + seq.charAt(i)) % modulus;
    19	        }
    20	        return hash;
    21	    }
    22	
    23	    @Override
    24	    public int highOrderFactor(int patternLength) {
    25	        int h = 1;
    26	        for (int i = 0; i < patternLength - 1; i++) {
    27	            h = (h * radix) % modulus;
    28	        }
    29	        return h;
    30	    }
    31	
    32	    @Override
    33	    public int roll(int currentHash, char leaving, char entering, int highOrderFactor) {
    34	        int hash = (radix * (currentHash - leaving * highOrderFactor) + entering) % modulus;
    35	        if (hash < 0) hash += modulus;
    36	        return hash;
    37	    }
    38	}

